      "extensionTrabajo": "Comprende todas las labores requeridas para la correcta ejecución de: SUMINISTRO Y TRANSPORTE DE ESTRUCTURA AUTOSOPORTANTE FORMADA POR DOS POSTES DE 11,28 MTS E.C.= 295 KG.. Incluye suministro de insumos certificados, transporte hasta el sitio de obra, maniobras de izado/colocación, mano de obra calificada bajo LOTTT y pruebas de aceptación final.",
      "procedimientoEjecucion": "Los trabajos se llevarán a cabo siguiendo estrictamente las especificaciones técnicas de PDVSA y normas COVENIN aplicables. El contratista verificará niveles, alineación, especificaciones de fábrica y condiciones seguras antes de iniciar las actividades.",
